    gks->m0_max = gkyl_cu_malloc(app->basis.num_basis*sizeof(double));
  }
  else {
    gks->omega_cfl = gkyl_malloc(sizeof(double));
    gks->m0_max = gkyl_malloc(app->basis.num_basis*sizeof(double));
  }

